package io.airbyte.api.client

import dev.failsafe.RetryPolicy
import io.airbyte.api.client.generated.ScimConfigApi
import io.airbyte.api.client.model.generated.EnableScimRequestBody
import io.airbyte.api.client.model.generated.OrganizationIdRequestBody
import io.airbyte.api.client.model.generated.ScimIdpProvider
import okhttp3.OkHttpClient
import okhttp3.mockwebserver.MockResponse
import okhttp3.mockwebserver.MockWebServer
import okhttp3.mockwebserver.SocketPolicy
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.AfterEach
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import java.io.IOException
import java.util.UUID

class ScimConfigApiRetryTest {
  private lateinit var server: MockWebServer
  private lateinit var client: ScimConfigApi

  @BeforeEach
  fun setUp() {
    server = MockWebServer()
    server.start()
    val sharedHttpClient = OkHttpClient.Builder().retryOnConnectionFailure(true).build()
    client =
      AirbyteApiClient(
        basePath = server.url("/").toString(),
        policy = RetryPolicy.ofDefaults(),
        httpClient = sharedHttpClient,
      ).scimConfigApi
  }

  @AfterEach
  fun tearDown() {
    server.shutdown()
  }

  @Test
  fun `initial enable is not retried after the response is lost`() {
    enqueueLostResponses()

    assertThrows<IOException> {
      client.enableScim(EnableScimRequestBody(UUID.randomUUID(), ScimIdpProvider.OKTA))
    }

    assertThat(server.requestCount).isEqualTo(1)
  }

  @Test
  fun `token rotation is not retried after the response is lost`() {
    enqueueLostResponses()

    assertThrows<IOException> {
      client.rotateScimToken(OrganizationIdRequestBody(UUID.randomUUID()))
    }

    assertThat(server.requestCount).isEqualTo(1)
  }

  @Test
  fun `directly constructed client disables OkHttp retries`() {
    val httpClient = directClient().client as OkHttpClient

    assertThat(httpClient.retryOnConnectionFailure).isFalse()
  }

  @Test
  fun `directly constructed client does not retry initial enable after the response is lost`() {
    enqueueLostResponses()

    assertThrows<IOException> {
      directClient().enableScim(EnableScimRequestBody(UUID.randomUUID(), ScimIdpProvider.OKTA))
    }

    assertThat(server.requestCount).isEqualTo(1)
  }

  @Test
  fun `directly constructed client does not retry token rotation after the response is lost`() {
    enqueueLostResponses()

    assertThrows<IOException> {
      directClient().rotateScimToken(OrganizationIdRequestBody(UUID.randomUUID()))
    }

    assertThat(server.requestCount).isEqualTo(1)
  }

  private fun directClient(): ScimConfigApi = ScimConfigApi(basePath = server.url("/").toString())

  private fun enqueueLostResponses() {
    repeat(3) {
      server.enqueue(MockResponse().setSocketPolicy(SocketPolicy.DISCONNECT_AFTER_REQUEST))
    }
  }
}

import { fireEvent, screen } from "@testing-library/react";

import { render } from "test-utils";

import { useAgentsProvisioningStatus } from "core/api";
import { useIsCloudApp } from "core/utils/app";

import { InstallMcpPage } from "./InstallMcpPage";
import { buildCursorDeeplink, CLOUD_MCP_URL } from "./mcpInstallConfigs";
import { useShowAgentsOptIn } from "./useShowAgentsOptIn";

jest.mock("core/api", () => ({
  useAgentsProvisioningStatus: jest.fn(),
}));

jest.mock("core/utils/app", () => ({
  useIsCloudApp: jest.fn(),
}));

jest.mock("core/utils/links", () => ({
  links: {
    airbyteMcpDocs: "https://docs.airbyte.com/platform/airbyte-mcp",
  },
}));

jest.mock("./useShowAgentsOptIn", () => ({
  useShowAgentsOptIn: jest.fn(),
}));

const mockUseAgentsProvisioningStatus = useAgentsProvisioningStatus as jest.MockedFunction<
  typeof useAgentsProvisioningStatus
>;
const mockUseIsCloudApp = useIsCloudApp as jest.MockedFunction<typeof useIsCloudApp>;
const mockUseShowAgentsOptIn = useShowAgentsOptIn as jest.MockedFunction<typeof useShowAgentsOptIn>;

describe("InstallMcpPage", () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockUseIsCloudApp.mockReturnValue(true);
    mockUseShowAgentsOptIn.mockReturnValue(true);
    mockUseAgentsProvisioningStatus.mockReturnValue({
      is_enrolled: true,
      external_cloud_eligible: true,
    } as never);
  });

  it("renders the install page and cloud MCP URL", async () => {
    await render(<InstallMcpPage />);

    expect(screen.getByRole("heading", { name: "Install MCP" })).toBeInTheDocument();
    expect(screen.getAllByText(CLOUD_MCP_URL, { exact: false }).length).toBeGreaterThan(0);
    expect(screen.getAllByRole("heading", { level: 2 }).map((heading) => heading.textContent)).toEqual([
      "Paste a URL",
      "One click install",
      "CLI command",
      "JSON config file",
    ]);
    expect(screen.getAllByRole("button", { name: "Copy" })).toHaveLength(6);
    expect(screen.getByText(/codex mcp add airbyte/)).toBeInTheDocument();
    expect(screen.getByText(/"servers":/)).toBeInTheDocument();
    expect(screen.getByText(/"mcpServers":/)).toBeInTheDocument();
  });

  it("opens the Cursor install deeplink", async () => {
    const open = jest.spyOn(window, "open").mockImplementation(() => null);

    await render(<InstallMcpPage />);
    fireEvent.click(screen.getByTestId("installMcp-cursor"));

    expect(open).toHaveBeenCalledWith(buildCursorDeeplink(CLOUD_MCP_URL), "_blank");
    open.mockRestore();
  });

  it("renders nothing when the agents opt-in is disabled", async () => {
    mockUseShowAgentsOptIn.mockReturnValue(false);

    const { container } = await render(<InstallMcpPage />);

    expect(screen.queryByRole("heading", { name: "Install MCP" })).not.toBeInTheDocument();
    expect(container.firstChild).toBeEmptyDOMElement();
  });
});

import {
  buildClaudeCodeCommand,
  buildCodexCommand,
  buildCursorConfig,
  buildCursorDeeplink,
  buildVsCodeCliCommand,
  buildVsCodeConfig,
  buildVsCodeDeeplink,
  buildVsCodeInsidersDeeplink,
  CLOUD_MCP_URL,
} from "./mcpInstallConfigs";

const TEST_URL = "https://mcp.example.com/mcp";

const unwrapVsCodeRedirect = (installUrl: string, redirectHost: string): string => {
  const prefix = `https://${redirectHost}/redirect?url=`;
  expect(installUrl.startsWith(prefix)).toBe(true);
  return decodeURIComponent(installUrl.slice(prefix.length));
};

describe("mcpInstallConfigs", () => {
  it("exports the cloud MCP server URL", () => {
    expect(CLOUD_MCP_URL).toBe("https://mcp.airbyte.com/mcp");
  });

  it("builds a Cursor deeplink with base64-encoded config and server name", () => {
    const deeplink = buildCursorDeeplink(TEST_URL);
    expect(deeplink.startsWith("cursor://anysphere.cursor-deeplink/mcp/install?")).toBe(true);
    expect(deeplink).toContain("name=airbyte");
    const configParam = new URL(deeplink.replace("cursor://", "http://cursor/")).searchParams.get("config");
    expect(configParam).not.toBeNull();
    const decoded = JSON.parse(atob(configParam!));
    expect(decoded).toEqual({ url: TEST_URL });
  });

  it.each([
    { variant: "stable" as const, build: buildVsCodeDeeplink, scheme: "vscode", redirectHost: "vscode.dev" },
    {
      variant: "insiders" as const,
      build: buildVsCodeInsidersDeeplink,
      scheme: "vscode-insiders",
      redirectHost: "insiders.vscode.dev",
    },
  ])(
    "builds a VS Code $variant install URL via the redirect wrapper with a flat payload",
    ({ build, scheme, redirectHost }) => {
      const installUrl = build(TEST_URL);
      const deeplink = unwrapVsCodeRedirect(installUrl, redirectHost);

      expect(deeplink.startsWith(`${scheme}:mcp/install?`)).toBe(true);
      expect(deeplink.startsWith(`${scheme}://`)).toBe(false);

      const encoded = deeplink.slice(`${scheme}:mcp/install?`.length);
      const decoded = JSON.parse(decodeURIComponent(encoded));
      expect(decoded).toEqual({ name: "airbyte", type: "http", url: TEST_URL });
      expect(decoded).not.toHaveProperty("config");
    }
  );

  it("builds the Claude Code CLI command", () => {
    expect(buildClaudeCodeCommand(TEST_URL)).toBe(`claude mcp add --transport http airbyte ${TEST_URL}`);
  });

  it("builds the Codex CLI command", () => {
    expect(buildCodexCommand(TEST_URL)).toBe(`codex mcp add airbyte --url ${TEST_URL}`);
  });

  it("builds the Cursor JSON config", () => {
    expect(buildCursorConfig(TEST_URL)).toBe(JSON.stringify({ mcpServers: { airbyte: { url: TEST_URL } } }, null, 2));
  });

  it("builds the VS Code JSON config", () => {
    expect(buildVsCodeConfig(TEST_URL)).toBe(
      JSON.stringify({ servers: { airbyte: { type: "http", url: TEST_URL } } }, null, 2)
    );
  });

  it("builds the VS Code CLI command", () => {
    expect(buildVsCodeCliCommand(TEST_URL)).toBe(
      `code --add-mcp '${JSON.stringify({ name: "airbyte", type: "http", url: TEST_URL })}'`
    );
  });
});

