import { useFusionUsage } from "core/api/cloud";
import { FusionUsageRead } from "core/api/types/AirbyteClient";
import messages from "locales/en.json";

import { AgentToolCallUsage } from "./AgentToolCallUsage";

jest.mock("core/api/cloud", () => ({ useFusionUsage: jest.fn() }));

const data: FusionUsageRead = {
  organizationId: "org",
  freeCapsApplicable: true,
  day: { used: 0, limit: 300, windowStart: "2026-10-02T00:00:00Z", resetsAt: "2026-10-03T00:00:00Z" },
  month: { used: 38_500, limit: 100_000, windowStart: "2026-10-01T00:00:00Z", resetsAt: "2026-11-01T00:00:00Z" },
};
const refetch = jest.fn();

type UsageState = Pick<
  ReturnType<typeof useFusionUsage>,
  "data" | "isEligible" | "isInitialLoading" | "isError" | "refetch"
>;

const renderCard = (overrides: Partial<UsageState> = {}) => {
  const query: UsageState = {
    data,
    isEligible: true,
    isInitialLoading: false,
    isError: false,
    refetch,
    ...overrides,
  };
  jest.mocked(useFusionUsage).mockReturnValue(query as ReturnType<typeof useFusionUsage>);
  return render(
    <IntlProvider locale="en" messages={messages}>
      <AgentToolCallUsage />
    </IntlProvider>
  );
};

describe("AgentToolCallUsage", () => {
  beforeEach(() => jest.clearAllMocks());

  it("renders monthly organization totals independently of daily usage", () => {
    renderCard();
    expect(screen.getByTestId("agent-tool-call-used")).toHaveTextContent("38,500");
    expect(screen.getByTestId("agent-tool-call-limit")).toHaveTextContent("100,000");
    expect(screen.getByTestId("agent-tool-call-percentage")).toHaveTextContent("38.5%");
    expect(screen.getByRole("progressbar")).toHaveAttribute("aria-valuenow", "38.5");
    expect(screen.getByRole("link", { name: "Learn more →" })).toHaveAttribute(
      "href",
      "https://docs.airbyte.com/platform/airbyte-mcp"
    );
  });

  it("renders zero usage", () => {
    renderCard({ data: { ...data, month: { ...data.month, used: 0 } } });
    expect(screen.getByTestId("agent-tool-call-used")).toHaveTextContent("0");
    expect(screen.getByTestId("agent-tool-call-percentage")).toHaveTextContent("0%");
  });

  it.each([100_000, 110_000])("renders the exhausted state at %s calls and caps the bar at 100%", (used) => {
    renderCard({ data: { ...data, month: { ...data.month, used } } });
    expect(screen.getByTestId("agent-tool-call-percentage")).toHaveTextContent(`${used / 1000}%`);
    const bar = screen.getByRole("progressbar");
    expect(bar).toHaveAttribute("aria-valuenow", "100");
    expect(bar.firstChild).toHaveStyle({ width: "100%" });
    expect(bar.firstChild).toHaveClass("usage__fill--exhausted");
  });

  it("does not turn unavailable usage into zero and offers retry", () => {
    renderCard({ data: { ...data, month: { ...data.month, used: null } } });
    expect(screen.getByTestId("agent-tool-call-used")).toHaveTextContent("Unavailable");
    expect(screen.queryByRole("progressbar")).not.toBeInTheDocument();
    fireEvent.click(screen.getByRole("button", { name: "Try again" }));
    expect(refetch).toHaveBeenCalledTimes(1);
  });

  it("shows unlimited and untracked values without inventing a percentage", () => {
    renderCard({ data: { ...data, month: { ...data.month, used: null, limit: null } } });
    expect(screen.getByTestId("agent-tool-call-used")).toHaveTextContent("Not tracked");
    expect(screen.getByTestId("agent-tool-call-limit")).toHaveTextContent("Unlimited");
    expect(screen.getByTestId("agent-tool-call-percentage")).toHaveTextContent("N/A");
    expect(screen.queryByRole("progressbar")).not.toBeInTheDocument();
  });

  it("does not divide by a zero limit", () => {
    renderCard({ data: { ...data, month: { ...data.month, used: 0, limit: 0 } } });
    expect(screen.getByTestId("agent-tool-call-percentage")).toHaveTextContent("N/A");
    expect(screen.queryByRole("progressbar")).not.toBeInTheDocument();
  });

  it("does not present free allowances when they do not apply", () => {
    renderCard({ data: { ...data, freeCapsApplicable: false } });
    expect(screen.getByText("Free tool-call allowances do not apply to your organization.")).toBeInTheDocument();
    expect(screen.queryByTestId("agent-tool-call-used")).not.toBeInTheDocument();
    expect(screen.queryByText(/Tool calls are free/)).not.toBeInTheDocument();
  });

  it("renders inline failures and retries the query", () => {
    renderCard({ data: undefined, isError: true });
    expect(screen.getByText("Unable to load tool-call usage. Please try again.")).toBeInTheDocument();
    fireEvent.click(screen.getByRole("button", { name: "Try again" }));
    expect(refetch).toHaveBeenCalledTimes(1);
  });

  it("renders an accessible loading state without totals", () => {
    renderCard({ data: undefined, isInitialLoading: true });
    expect(screen.getByLabelText("Loading usage data...")).toHaveAttribute("aria-busy", "true");
    expect(screen.queryByTestId("agent-tool-call-used")).not.toBeInTheDocument();
  });

  it("hides the card for ineligible organizations even if cached data is present", () => {
    renderCard({ isEligible: false });
    expect(screen.queryByTestId("agent-tool-call-usage")).not.toBeInTheDocument();
  });
});

import { act, fireEvent, screen, within } from "@testing-library/react";

import { render } from "test-utils";

import { PricingCalculator } from "./PricingCalculator";

jest.useFakeTimers();

const slider = () => screen.getByRole("slider", { name: "Monthly credits" });
const creditsField = () => screen.getByRole("spinbutton", { name: "Monthly credits" });
const tile = (name: "standard-price" | "plus-price" | "rows" | "data-volume") =>
  screen.getByTestId(`pricing-calculator-${name}`);
const recommendation = () => screen.getByTestId("pricing-calculator-recommendation");

const setSlider = (credits: number) => fireEvent.change(slider(), { target: { value: String(credits) } });
const typeCredits = (value: string) => fireEvent.change(creditsField(), { target: { value } });
const settleDebounce = () => act(() => jest.advanceTimersByTime(300));

describe("PricingCalculator", () => {
  afterAll(() => {
    jest.useRealTimers();
  });

  it("starts at 5 credits with Standard as the cheaper plan", async () => {
    await render(<PricingCalculator />);

    expect(screen.getByRole("heading", { name: "Pricing calculator" })).toBeInTheDocument();
    expect(slider()).toHaveValue("5");
    expect(creditsField()).toHaveValue(5);
    expect(tile("standard-price")).toHaveTextContent("$20/ mo");
    expect(tile("standard-price")).toHaveAttribute("data-highlighted", "true");
    expect(tile("plus-price")).toHaveTextContent("$189/ mo");
    expect(tile("plus-price")).toHaveAttribute("data-highlighted", "false");
    expect(tile("rows")).toHaveTextContent("830Krows / mo");
    expect(tile("data-volume")).toHaveTextContent("1GB / mo");
    expect(recommendation()).toHaveTextContent("Standard is the most cost-effective choice.");
  });

  it("updates the controls immediately but recomputes prices only after the 300ms debounce", async () => {
    await render(<PricingCalculator />);

    setSlider(1000);

    expect(creditsField()).toHaveValue(1000);
    expect(tile("standard-price")).toHaveTextContent("$20");

    settleDebounce();

    expect(tile("standard-price")).toHaveTextContent("$4,995/ mo");
    expect(tile("standard-price")).toHaveAttribute("data-highlighted", "false");
    expect(tile("plus-price")).toHaveTextContent("$3,199/ mo");
    expect(tile("plus-price")).toHaveAttribute("data-highlighted", "true");
    expect(tile("rows")).toHaveTextContent("166Mrows / mo");
    expect(tile("data-volume")).toHaveTextContent("250GB / mo");
    expect(recommendation()).toHaveTextContent("Plus with 1000 credits is the most cost-effective choice.");
  });

  it("recommends Pro at 2000 credits while still quoting both self-serve plans", async () => {
    await render(<PricingCalculator />);

    setSlider(2000);
    settleDebounce();

    expect(tile("standard-price")).toHaveTextContent("$9,995/ mo");
    expect(tile("plus-price")).toHaveTextContent("$4,999/ mo");
    expect(tile("plus-price")).toHaveAttribute("data-highlighted", "true");
    expect(tile("rows")).toHaveTextContent("332Mrows / mo");
    expect(tile("data-volume")).toHaveTextContent("500GB / mo");
    expect(recommendation()).toHaveTextContent(
      "Above 2000 credits per month, Pro is a more cost-effective choice. Talk to Sales."
    );
    const salesLink = within(recommendation()).getByRole("link", { name: "Talk to Sales" });
    expect(salesLink).toHaveAttribute("href", "https://airbyte.com/talk-to-sales");
    expect(salesLink).toHaveAttribute("target", "_blank");
  });

  it("does not render a Talk to Sales link below 2000 credits", async () => {
    await render(<PricingCalculator />);

    setSlider(1000);
    settleDebounce();

    expect(within(recommendation()).queryByRole("link")).not.toBeInTheDocument();
  });

  it("accepts typed credits and shows cents when the Plus quote has them", async () => {
    await render(<PricingCalculator />);

    typeCredits("750");
    settleDebounce();

    expect(slider()).toHaveValue("750");
    expect(tile("plus-price")).toHaveTextContent("$2,836.50/ mo");
    expect(recommendation()).toHaveTextContent("Plus with 500 credits is the most cost-effective choice.");
  });

  it("clamps typed credits to the slider range", async () => {
    await render(<PricingCalculator />);

    typeCredits("5000");
    expect(slider()).toHaveValue("2000");
    expect(creditsField()).toHaveValue(2000);

    typeCredits("-3");
    settleDebounce();
    expect(slider()).toHaveValue("0");
    expect(tile("standard-price")).toHaveTextContent("$20/ mo");
    expect(tile("rows")).toHaveTextContent("0rows / mo");
    expect(tile("data-volume")).toHaveTextContent("0MB / mo");
  });

  it("shows megabytes below one gigabyte", async () => {
    await render(<PricingCalculator />);

    setSlider(3);
    settleDebounce();

    expect(tile("data-volume")).toHaveTextContent("750MB / mo");
  });

  it("keeps the last valid credits while the field is empty and restores them on blur", async () => {
    await render(<PricingCalculator />);

    setSlider(60);
    typeCredits("");

    expect(creditsField()).toHaveValue(null);
    expect(slider()).toHaveValue("60");

    fireEvent.blur(creditsField());
    settleDebounce();

    expect(creditsField()).toHaveValue(60);
    expect(tile("plus-price")).toHaveTextContent("$289/ mo");
    expect(recommendation()).toHaveTextContent("Plus with 40 credits is the most cost-effective choice.");
  });
});

import {
  calculatePlusQuote,
  calculateStandardPrice,
  clampCredits,
  estimatePricing,
  MAX_CREDITS,
  MIN_CREDITS,
} from "./pricingEstimate";

describe("calculateStandardPrice", () => {
  it.each([
    [0, 20],
    [5, 20],
    [6, 25],
    [1000, 4995],
    [2000, 9995],
  ])("prices %i credits on Standard at $%i", (credits, price) => {
    expect(calculateStandardPrice(credits)).toBe(price);
  });
});

describe("calculatePlusQuote", () => {
  it.each([
    [0, 40, 189],
    [5, 40, 189],
    [6, 40, 189],
    [39, 40, 189],
    [60, 40, 289],
    [92, 100, 449],
    [100, 100, 449],
    [750, 500, 2836.5],
    [1000, 1000, 3199],
    [1480, 2000, 4999],
    [1720, 2000, 4999],
    [2000, 2000, 4999],
  ])("prices %i credits on Plus %i at $%s", (credits, tierCredits, price) => {
    expect(calculatePlusQuote(credits)).toEqual({ tierCredits, price });
  });

  it("prefers the higher tier when a lower tier plus overage costs the same", () => {
    expect(calculatePlusQuote(92)).toEqual({ tierCredits: 100, price: 449 });
    expect(calculatePlusQuote(1480)).toEqual({ tierCredits: 2000, price: 4999 });
  });
});

describe("estimatePricing", () => {
  it("recommends Standard for every credit count from 0 through 38", () => {
    for (let credits = 0; credits <= 38; credits++) {
      expect(estimatePricing(credits).recommendation).toEqual({ plan: "standard" });
      expect(estimatePricing(credits).cheaperPlan).toBe("standard");
    }
  });

  it("recommends a Plus tier for every credit count from 39 through 1999", () => {
    for (let credits = 39; credits < MAX_CREDITS; credits++) {
      expect(estimatePricing(credits).recommendation.plan).toBe("plus");
      expect(estimatePricing(credits).cheaperPlan).toBe("plus");
    }
  });

  it.each([
    [39, 40],
    [60, 40],
    [92, 100],
    [750, 500],
    [1720, 2000],
  ])("names the cheapest Plus tier for %i credits", (credits, tierCredits) => {
    expect(estimatePricing(credits).recommendation).toEqual({ plan: "plus", tierCredits });
  });

  it("recommends Pro at the 2000 credit ceiling while still quoting Plus", () => {
    const estimate = estimatePricing(2000);
    expect(estimate.recommendation).toEqual({ plan: "pro" });
    expect(estimate.plus).toEqual({ tierCredits: 2000, price: 4999 });
    expect(estimate.standardPrice).toBe(9995);
    expect(estimate.cheaperPlan).toBe("plus");
  });

  it.each([
    [0, 0, 0],
    [5, 830_000, 1250],
    [1000, 166_000_000, 250_000],
    [2000, 332_000_000, 500_000],
  ])("converts %i credits into %i rows and %i megabytes", (credits, rows, megabytes) => {
    expect(estimatePricing(credits)).toEqual(expect.objectContaining({ rows, megabytes }));
  });
});

describe("clampCredits", () => {
  it.each([
    [-5, MIN_CREDITS],
    [0, 0],
    [10.6, 11],
    [2000, MAX_CREDITS],
    [2500, MAX_CREDITS],
  ])("clamps %s to %i", (input, expected) => {
    expect(clampCredits(input)).toBe(expected);
  });
});

